  const raw=[point(i,j),point(i+1,j),point(i+1,j+1),point(i,j+1)],vs=[];
  for(const p of raw)if(!vs.some(q=>length3(sub3(p,q))<1e-9))vs.push(p);
  if(vs.length<3)continue;
