  let lo=0,hi=1;for(let i=0;i<60;i++){const x=(lo+hi)/2,u=shape==='sphere'?2*x:x,value=shape==='sphere'?(3*u*u-u*u*u)/4:(3*u-u*u*u)/2;if(value<f)lo=x;else hi=x;}return (lo+hi)/2;
