   const scene=kind==='net'?{mesh:presetNetMesh('cube',0),yaw:0,pitch:.12}:kind==='volume'?{mesh:unitCubeMesh({p:3,l:2,t:2},8)}:kind==='area'?{shape:'pyramid'}:{mesh:compositionMesh('roof',{a:3,t:2},.5)};
