  if(problem.variables.s!==undefined){let root=problem.context==='cube-pyramid'||problem.shape==='pyramid'?'\u221A(t\xB2 + (a/2)\xB2)':problem.shape==='tetrahedron'?'\u221A(t\xB2 + (a\u221A3/6)\xB2)':'\u221A(j\xB2 + t\xB2)';append(this.text('slant'),root+' cm '+(this.language()==='en'?'(keep exact)':'(kekalkan tepat)'));}
